public Server start(@Nonnull
Jooby application) {
    try // PATH: Test should invoke the next Undertow.start(...) [step in execution path]
    {
        applications.add(application);
        addShutdownHook();
        HttpHandler handler = new UtowHandler(applications.get(0), options.getBufferSize(), options.getMaxRequestSize(), options.getDefaultHeaders());
        if (options.getCompressionLevel() != null) {
            int compressionLevel = options.getCompressionLevel();
            handler = new EncodingHandler(handler, new ContentEncodingRepository().addEncodingHandler("gzip", new GzipEncodingProvider(compressionLevel), _100).addEncodingHandler("deflate", new DeflateEncodingProvider(compressionLevel), _10));
        }
        if (options.isExpectContinue() == Boolean.TRUE) {
            handler = new HttpContinueReadHandler(handler);
        }
        Undertow.Builder builder = /**
         * Worker:
         */
        /**
         * Server:
         */
        // HTTP/1.1 is keep-alive by default, turn this option off
        /**
         * Socket :
         */
        Undertow.builder().setBufferSize(options.getBufferSize()).setSocketOption(Options.BACKLOG, BACKLOG).setServerOption(UndertowOptions.ALWAYS_SET_KEEP_ALIVE, false).setServerOption(UndertowOptions.ALLOW_EQUALS_IN_COOKIE_VALUE, true).setServerOption(UndertowOptions.ALWAYS_SET_DATE, options.getDefaultHeaders()).setServerOption(UndertowOptions.RECORD_REQUEST_START_TIME, false).setServerOption(UndertowOptions.DECODE_URL, false).setIoThreads(options.getIoThreads()).setWorkerOption(Options.WORKER_NAME, "worker").setWorkerThreads(options.getWorkerThreads()).setHandler(handler);
        if (!options.isHttpsOnly()) {
            builder.addHttpListener(options.getPort(), options.getHost());
        }
        if ((options.isHttp2() == null) || (options.isHttp2() == Boolean.TRUE)) {
            stream(spliteratorUnknownSize(ServiceLoader.load(Http2Configurer.class).iterator(), Spliterator.ORDERED), false).filter(it -> it.support(Undertow.Builder.class)).findFirst().ifPresent(extension -> {
                extension.configure(builder);
                options.setHttp2(Boolean.TRUE);
            });
        }
        SSLContext sslContext = options.getSSLContext(application.getEnvironment().getClassLoader());
        if (sslContext != null) {
            builder.addHttpsListener(options.getSecurePort(), options.getHost(), sslContext);
            SslOptions ssl = options.getSsl();
            builder.setSocketOption(Options.SSL_ENABLED_PROTOCOLS, Sequence.of(ssl.getProtocol()));
            Optional.ofNullable(options.getSsl()).map(SslOptions::getClientAuth).map(this::toSslClientAuthMode).ifPresent(clientAuth -> builder.setSocketOption(Options.SSL_CLIENT_AUTH_MODE, clientAuth));
        } else if (options.isHttpsOnly()) {
            throw new IllegalArgumentException("Server configured for httpsOnly, but ssl options not set");
        }
        server = builder.build();
        server.start();
        // NOT IDEAL, but we need to fire onStart after server.start to get access to Worker
        fireStart(applications, server.getWorker());
        fireReady(Collections.singletonList(application));
        return this;
    } catch (RuntimeException x) {
        Throwable sourceException = x;
        Throwable cause = Optional.ofNullable(x.getCause()).orElse(x);
        if (Server.isAddressInUse(cause)) {
            sourceException = new BindException("Address already in use: " + options.getPort());
        }
        throw SneakyThrows.propagate(sourceException);
    }
